-- Only a SHA-256 digest of a high-entropy 256-bit secret is stored.
-- expires_at NULL means valid until revoked (owner account must remain ACTIVE).
CREATE TABLE IF NOT EXISTS "api_key" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "owner_id" BIGINT NOT NULL REFERENCES "users" ("id") ON DELETE CASCADE,
    "name" VARCHAR(80) NOT NULL,
    "key_hash" VARCHAR(64) NOT NULL UNIQUE,
    "key_prefix" VARCHAR(30) NOT NULL,
    "scopes" VARCHAR(255) NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ,
    "revoked_at" TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS "idx_api_key_owner_id" ON "api_key" ("owner_id");
